import{_ as e,o as s,c as t,ag as i}from"./chunks/framework.By9v0nLp.js";const g=JSON.parse('{"title":"Starting Dialogs","description":"","frontmatter":{},"headers":[],"relativePath":"using/starting.md","filePath":"using/starting.md"}'),n={name:"using/starting.md"};function o(l,a,r,d,p,c){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="starting-dialogs" tabindex="-1">Starting Dialogs <a class="header-anchor" href="#starting-dialogs" aria-label="Permalink to &quot;Starting Dialogs&quot;">​</a></h1><p>A conversation can start from a character the player right-clicks, a command, a quest, a command block, or anything else that runs commands.</p><h2 id="talk-to-a-mob-or-npc" tabindex="-1">Talk to a mob or NPC <a class="header-anchor" href="#talk-to-a-mob-or-npc" aria-label="Permalink to &quot;Talk to a mob or NPC&quot;">​</a></h2><p>Bind a dialog to any entity, and right-clicking it starts the conversation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dialog bind &lt;entities&gt; &lt;dialog&gt; [node]</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dialog bind @e[type=villager,limit=1,sort=nearest] mypack:elder</span></span></code></pre></div><ul><li>Works on any entity except players: villagers, mobs, armor stands, Easy NPC characters.</li><li>The binding is saved with the entity, so it survives restarts.</li><li>Right-clicking replaces the entity&#39;s normal interaction. A bound villager talks instead of opening its trades.</li><li>While talking, a mob turns to face the player and stops walking.</li><li>The conversation ends if the player walks more than <strong>8 blocks</strong> away, the character dies, or one of them changes dimension.</li><li>Add a node name to start somewhere other than the dialog&#39;s <code>start</code>: <code>/dialog bind @e[...] mypack:elder menu</code>.</li></ul><p>Remove a binding with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dialog unbind &lt;entities&gt;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Name your NPCs</p><p>Give characters a name tag or a tag first, so the selector finds the right one later: <code>/dialog bind @e[tag=elder,limit=1] mypack:elder</code>.</p></div><h2 id="with-a-command" tabindex="-1">With a command <a class="header-anchor" href="#with-a-command" aria-label="Permalink to &quot;With a command&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dialog start &lt;players&gt; &lt;dialog&gt; [node]</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dialog start @p mypack:welcome</span></span>
<span class="line"><span>/dialog start Steve mypack:elder menu</span></span></code></pre></div><p>The conversation opens a moment later, at the end of the current game tick. A player can only be in one conversation at a time: starting another replaces the open one.</p><h2 id="from-ftb-quests" tabindex="-1">From FTB Quests <a class="header-anchor" href="#from-ftb-quests" aria-label="Permalink to &quot;From FTB Quests&quot;">​</a></h2><p>Add a <strong>command reward</strong> to a quest:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dialog start {p} mypack:elder</span></span></code></pre></div><p><code>{p}</code> is the player who completed the quest. <code>/dialog</code> needs permission level 2, so if the reward runs with the player&#39;s own permissions, turn on the reward&#39;s option to run with raised permissions.</p><p>Rewards can also change the conversation itself: <code>/dialog flag set {p} quest_wood_done</code> or <code>/dialog relationship add {p} elder 3</code>.</p><h2 id="from-easy-npc" tabindex="-1">From Easy NPC <a class="header-anchor" href="#from-easy-npc" aria-label="Permalink to &quot;From Easy NPC&quot;">​</a></h2><p>Give the NPC an action that runs a command when it&#39;s clicked, such as:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dialog start @p mypack:elder</span></span></code></pre></div><p>Or bind the dialog straight onto the Easy NPC with <code>/dialog bind</code>, as with any other entity.</p><h2 id="from-command-blocks-and-pressure-plates" tabindex="-1">From command blocks and pressure plates <a class="header-anchor" href="#from-command-blocks-and-pressure-plates" aria-label="Permalink to &quot;From command blocks and pressure plates&quot;">​</a></h2><p>A command block with <code>/dialog start @p mypack:sign</code> next to a pressure plate makes a talking sign. Use the narrator (<code>&quot;speaker&quot;: &quot;none&quot;</code>) and the <code>voice.typewriter</code> sound for a nice &quot;reading a note&quot; feel.</p><h2 id="from-nostalgic-memories" tabindex="-1">From Nostalgic Memories <a class="header-anchor" href="#from-nostalgic-memories" aria-label="Permalink to &quot;From Nostalgic Memories&quot;">​</a></h2><p>A memory&#39;s unlock commands can start a dialog, so a character can react the moment the player unlocks something. Going the other way, dialogs can check and grant memories with the <a href="/wiki/nostalgicdialog/logic/conditions#memory"><code>memory</code> condition</a> and <a href="/wiki/nostalgicdialog/logic/actions#memory"><code>memory</code> action</a>.</p><h2 id="teleporting-during-a-conversation" tabindex="-1">Teleporting during a conversation <a class="header-anchor" href="#teleporting-during-a-conversation" aria-label="Permalink to &quot;Teleporting during a conversation&quot;">​</a></h2><p>A conversation started with a <strong>command</strong> keeps going wherever the player goes, also into another dimension. Use a <a href="/wiki/nostalgicdialog/logic/actions#command"><code>command</code> action</a> to teleport and keep talking.</p><p>A conversation started by <strong>right-clicking a bound character</strong> ends when the player gets more than 8 blocks from that character, and a teleport counts. To teleport and keep talking, end the character&#39;s conversation with a logic node that teleports the player and starts a new dialog with a command. The new one isn&#39;t tied to the character:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;to_the_ruins&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;actions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;execute in mypack:story run tp @s 0 64 0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dialog start @s mypack:ruins_arrival&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="ending-a-conversation" tabindex="-1">Ending a conversation <a class="header-anchor" href="#ending-a-conversation" aria-label="Permalink to &quot;Ending a conversation&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dialog stop &lt;players&gt;</span></span></code></pre></div><p>This closes the box without counting the conversation as finished: no <code>on_end</code>, not marked as seen. The same happens when the player dies or logs out.</p>`,34)])])}const m=e(n,[["render",o]]);export{g as __pageData,m as default};
